#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

# ── 本向导自己的变量与路径（**在 STAGES 标记之下**，库本身不动）─────────────
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$ROOT/signing/local.env"          # write_env 写这里（已被 .gitignore 挡住）
REL_DIR="$ROOT/signing/release"             # 发布材料放这里（材料文件也不入库）
CLI_HOME="${CLASS_OUT_CLI_HOME:-/home/chemica/ChemicaWorkspace/toolchain/cli/command-line-tools}"
JAVA_HOME="${JAVA_HOME:-/home/chemica/ChemicaWorkspace/toolchain/jdk}"
JAR="$CLI_HOME/sdk/default/openharmony/toolchains/lib/hap-sign-tool.jar"
AGC="https://developer.huawei.com/consumer/cn/service/josp/agc/index.html"
PKG="com.chemica.classout"

mkdir -p "$REL_DIR"
have_rel() { find "$REL_DIR" -maxdepth 1 -iname "*.$1" 2>/dev/null | head -1; }

banner "ClassOUT 上架华为应用市场"

# ──────────────────────────────────────────────────────────────────────────
stage "账号：实名认证"
say "上架要求开发者账号完成实名认证；没实名连应用都建不了。"
open_url "https://developer.huawei.com/consumer/cn/"
step "登录后进「控制台 → 账号中心 → 实名认证」，确认状态是「已实名」。"
step "顺便确认：这个账号就是你现在用的那个（项目、证书、设备都挂在它下面）。"
note "调试证书有效期 2027-10-13；发布证书是另一套，第 4 步才建。"
pause "确认已实名后按 Enter"

# ──────────────────────────────────────────────────────────────────────────
stage "AGC：建项目 + 添加应用"
say "应用包名必须和应用里的一致，否则签名/上传都会对不上。"
open_url "$AGC"
step "「我的项目」→ 新建项目（名字随意，例如 ClassOUT）。"
step "项目里「添加应用」：平台选 **APP（HarmonyOS）**，包名填 **$PKG**。"
warn "包名创建后不能改。填错了只能删掉重建。"
step "应用名中英文都要填（审核会看）。"
pause "应用建好后按 Enter"

# ──────────────────────────────────────────────────────────────────────────
stage "本地：准备发布密钥库 + CSR"
say "私钥只在这台机器上生成，AGC 只收 CSR（理由见 signing/README.md）。"
if [[ -f "$REL_DIR/classout-release.p12" ]]; then
  note "signing/release/ 里已经有密钥库了 —— 跳过生成，直接用现成的。"
elif confirm "直接复用调试那把签名密钥（signing/classout.p12）吗？"; then
  cp "$ROOT/signing/classout.p12" "$REL_DIR/classout-release.p12"
  write_env CLASS_OUT_RELEASE_KEY_ALIAS "classout-debug"
  note "已复制；别名沿用 classout-debug，并写进了 local.env。"
else
  ask_secret CLASS_OUT_KEY_PWD "给发布密钥库设个口令："
  write_env CLASS_OUT_KEY_PWD "$CLASS_OUT_KEY_PWD"
  ask CLASS_OUT_RELEASE_KEY_ALIAS "密钥别名（直接 Enter = classout-release）："
  [[ -n "$CLASS_OUT_RELEASE_KEY_ALIAS" ]] || CLASS_OUT_RELEASE_KEY_ALIAS="classout-release"
  write_env CLASS_OUT_RELEASE_KEY_ALIAS "$CLASS_OUT_RELEASE_KEY_ALIAS"
  ask CSR_SUBJECT "证书主题（**不能有中文**，Enter = C=CN,O=ClassOUT,OU=Dev）："
  [[ -n "$CSR_SUBJECT" ]] || CSR_SUBJECT="C=CN,O=ClassOUT,OU=Dev"
  say "生成密钥库与 CSR …"
  "$JAVA_HOME/bin/java" -jar "$JAR" generate-keypair \
    -keyAlias "$CLASS_OUT_RELEASE_KEY_ALIAS" -keyPwd "$CLASS_OUT_KEY_PWD" \
    -keyAlg ECC -keySize NIST-P-256 \
    -keystoreFile "$REL_DIR/classout-release.p12" -keystorePwd "$CLASS_OUT_KEY_PWD"
  "$JAVA_HOME/bin/java" -jar "$JAR" generate-csr \
    -keyAlias "$CLASS_OUT_RELEASE_KEY_ALIAS" -keyPwd "$CLASS_OUT_KEY_PWD" \
    -subject "$CSR_SUBJECT" -signAlg SHA256withECDSA \
    -keystoreFile "$REL_DIR/classout-release.p12" -keystorePwd "$CLASS_OUT_KEY_PWD" \
    -outFile "$REL_DIR/classout-release.csr"
  printf '  %s✓%s CSR：%s\n' "$GREEN" "$RESET" "$REL_DIR/classout-release.csr"
fi

# ──────────────────────────────────────────────────────────────────────────
stage "AGC：上传 CSR → 换发布证书（.cer）"
open_url "$AGC"
step "「证书、App ID 和 Profile」→「证书」→ 新增证书 → 类型选 **发布证书**。"
step "上传 CSR：signing/release/classout-release.csr"
note "（复用调试密钥的话，CSR 用 signing/classout.csr，别传错。）"
step "下载生成的 .cer，放进 $REL_DIR/"
warn "一个账号最多 3 个证书，别重复建。"
pause "把 .cer 放好之后按 Enter"
CER="$(have_rel cer)"
if [[ -n "$CER" ]]; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$CER"
else warn "还是没找到 .cer —— 第 6 步打发布包会失败"; fi

# ──────────────────────────────────────────────────────────────────────────
stage "AGC：建发布 Profile（.p7b）"
open_url "$AGC"
step "「证书、App ID 和 Profile」→「Profile」→ 新增 Profile → 类型选 **发布**。"
step "选刚建的发布证书 + 应用（包名 $PKG）。"
step "**发布 Profile 不用勾设备**（要勾设备的是调试/测试用的那种）。"
step "下载 .p7b，放进 $REL_DIR/"
pause "把 .p7b 放好之后按 Enter"
PROF="$(have_rel p7b)"
if [[ -n "$PROF" ]]; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$PROF"
else warn "还是没找到 .p7b —— 第 6 步打发布包会失败"; fi

# ──────────────────────────────────────────────────────────────────────────
stage "打发布包（这条命令替你完成）"
say "release 构建 → 发布证书签名 → 校验，一条命令到底（见 sign-release.sh）。"
warn "构建需要那个 locale shim 的 PATH（HANDOFF §23.5）："
note "export PATH=\"/home/chemica/ChemicaWorkspace/.locale-shim:\$PATH\""
if confirm "现在跑 ./sign-release.sh 吗？"; then
  "$ROOT/sign-release.sh"
  note "产物：dist/ClassOUT-<版本号>-release.app"
else
  SKIPPED+=("跑 ./sign-release.sh 打发布包")
fi

# ──────────────────────────────────────────────────────────────────────────
stage "AGC：上传 .app"
open_url "$AGC"
step "「我的应用」→ ClassOUT → 版本信息 → 上传软件包 → 选 dist/ 里那个 .app。"
step "版本号（versionCode）必须比已上架的高；首次上架用 app.json5 里现成的就行。"
note "平台会校验包名/证书/Profile 是否匹配 —— 前 5 步没做错就能过。"
pause "上传成功后按 Enter"

# ──────────────────────────────────────────────────────────────────────────
stage "AGC：填应用信息（最容易被打回的一页）"
open_url "$AGC"
step "图标 512×512：**必须是你拥有版权的图**。现在这张是自绘的（tools/make-icon.py 可重新生成）。"
step "截图 3–5 张：docs/manual/ 里有现成的真机截图（01–06）。"
step "描述：老实写「纯离线的课表 + 待办 + 计划」，别写没有的功能。"
step "分类：教育 / 工具（按 AGC 实际选项挑）。"
step "隐私政策链接：仓库里的 PRIVACY.md（Gitee 上的文件链接就能当链接用）。"
step "按提示补材料：**软件著作权 / 电子版权认证**、**APP 备案号**、联系邮箱。"
warn "PRIVACY.md 与应用内正文里的邮箱还是占位符 <在这里填你的邮箱>，提交前必须换成真的。"

# ──────────────────────────────────────────────────────────────────────────
stage "提交审核"
step "过一遍所有必填项（AGC 会把缺的标红）。"
step "提交审核：一般 1–7 个工作日；被驳回会写原因，改完重新提交即可。"
say "审核通过后可「立即发布」或「定时发布」。"
note "以后更新版本：升 AppScope/app.json5 的 versionCode/versionName → ./sign-release.sh → 重新上传提审。"

finish
